pthread_mutexattr_t attr;
int pshared_val;
int err;

// Initialize attributes
pthread_mutexattr_init(&attr);

// Set attribute (optional, often used for verification)
pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);

// Retrieve the process-shared attribute
err = pthread_mutexattr_getpshared(&attr, &pshared_val);

// pshared_val is PTHREAD_PROCESS_SHARED or PTHREAD_PROCESS_PRIVATE

pthread_mutexattr_destroy(&attr);
